#include "scarlett_cpu64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;assert(m.map(0x1000,4096,7)==GuestMemory64::Fault::none);unsigned total=0;
for(unsigned n:{16u,32u})for(unsigned op:{0x60u,0x61u,0x62u,0x68u,0x69u,0x6au,0x6cu,0x6du})for(bool mem:{false,true}){Cpu64State i;i.gpr[0]=0x1800;std::array<uint8_t,32> y{};for(unsigned j=0;j<32;++j){(j<16?i.xmm[4][j]:i.ymmHigh[4][j-16])=j+1;y[j]=j+65;(j<16?i.xmm[1][j]:i.ymmHigh[1][j-16])=y[j];}assert(m.write(0x1800,y)==GuestMemory64::Fault::none);assert(m.write(0x1000,std::array<uint8_t,4>{0xc5,uint8_t(0xd9|(n==32?4:0)),uint8_t(op),uint8_t(mem?0:0xc1)})==GuestMemory64::Fault::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&i);assert(s.rip==0x1004);unsigned w=op>=0x6c?8:1u<<(op&3),start=(op==0x6d||(op>=0x68&&op<=0x6a))?8:0;for(unsigned j=0;j<n;++j){unsigned k=j%16,lane=j/16*16;unsigned expected=lane+start+(k/(2*w))*w+k%w+((k/w)%2?65:1);assert((j<16?s.xmm[0][j]:s.ymmHigh[0][j-16])==expected);}if(n==16)for(auto v:s.ymmHigh[0])assert(v==0);++total;}
for(unsigned op:{0x16u,0x36u}){Cpu64State i;for(unsigned j=0;j<8;++j){(j<4?i.xmm[4][j*4]:i.ymmHigh[4][(j-4)*4])=7-j;(j<4?i.xmm[1][j*4]:i.ymmHigh[1][(j-4)*4])=j+10;}assert(m.write(0x1000,std::array<uint8_t,5>{0xc4,0xe2,0x5d,uint8_t(op),0xc1})==GuestMemory64::Fault::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&i);assert(s.rip==0x1005);for(unsigned j=0;j<8;++j)assert((j<4?s.xmm[0][j*4]:s.ymmHigh[0][(j-4)*4])==17-j);++total;}
ScarlettImports64 imports;std::array<uint8_t,16> fp{};uint64_t rax=0;assert(m.write(0x1800,std::array<uint8_t,7>{'-','1','2','.','5','x',0})==GuestMemory64::Fault::none);
for(auto name:{"atof","strtod","strtof"}){auto a=imports.registerImport("api-ms-win-crt-convert-l1-1-0.dll",name);assert(a&&imports.dispatch(a,m,0x1800,rax,0x1900,0,0,0,0,&fp));if(std::string(name)=="strtof"){float v;std::memcpy(&v,fp.data(),4);assert(v==-12.5f);}else{double v;std::memcpy(&v,fp.data(),8);assert(v==-12.5);}++total;}
for(auto name:{"modf","modff","_fdsign","lroundf"}){auto a=imports.registerImport("api-ms-win-crt-math-l1-1-0.dll",name);double d=-12.5;float f=-12.5f;if(std::string(name)=="modf")std::memcpy(fp.data(),&d,8);else std::memcpy(fp.data(),&f,4);assert(a&&imports.dispatch(a,m,0,rax,0x1900,0,0,0,0,&fp));if(std::string(name)=="modf"){std::memcpy(&d,fp.data(),8);assert(d==-.5);}else if(std::string(name)=="modff"){std::memcpy(&f,fp.data(),4);assert(f==-.5f);}else if(std::string(name)=="_fdsign")assert(rax==0x8000);else assert(uint32_t(rax)==uint32_t(-13));++total;}
std::cout<<"V69 tests passed: "<<total<<" cases\n";}
